{
  "status": "STABLE",
  "core_findings": [
    "Sampled training-position positives generally outrank negatives: negative-beats-positive rates are 2.23% for Movies, 5.05% for Industrial, 0.20% for Electronics and 0.04% for CDs. Industrial has the weakest separation, with a tenth-percentile margin of 0.8873.",
    "Mean embedding cosine ranges from 0.0491 to 0.2520; these values alone do not establish collapse. Paired-context effect estimates are omitted, so context sensitivity cannot be assessed."
  ],
  "key_implications": [
    "The measured training comparisons show strong separation, but do not establish validation HR@10 or generalization.",
    "Large Electronics and CDs margins are score-scale dependent and do not independently demonstrate better ranking quality."
  ],
  "evidence": {
    "headline_metrics": {
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0505,
      "Industrial_and_Scientific:pos_neg_margin_p10": 0.8873,
      "Electronics:pos_neg_margin_mean": 15.4316,
      "CDs_and_Vinyl:pos_neg_margin_mean": 18.7878,
      "Industrial_and_Scientific:embedding_mean_offdiagonal_cosine": 0.25200076000132715
    },
    "brief_metric_read": {
      "pos_neg_neg_beats_pos_rate": "Measured fraction of valid training-position margins below zero.",
      "pos_neg_margin_mean": "Raw score separation; magnitude depends on score scale.",
      "embedding_mean_offdiagonal_cosine": "Directional similarity, not a calibrated collapse measure.",
      "paired_recent_context": "All 200 selected users per category were scored, but effect estimates are absent from the supplied report."
    }
  }
}
